export const meta = {
  name: 'cmake-harvest',
  description: 'CMake research program phase 6: one opus agent harvests the wave just landed, rules on its surprises and follow-ups, and either commissions the next wave (revising the staged briefs) or declares convergence with authoring notes binding on the drafters',
  phases: [{ title: 'Harvest', detail: 'harvest the wave, apply the stop condition, commission the next wave or write the authoring notes', model: 'opus' }],
}

// Generated by mkharvest.py: the wave receipt is baked in because Workflow args have a size cap.
const H = __HARVEST__

const ROOT = '/home/mherwig/dev/grimoire-lore/.agents/worktrees/java'
const RESEARCH = ROOT + '/.agents/research'
const DATE = H.date
const WAVE = H.wave
const NEXT = WAVE + 1
const MODE = H.mode // 'commission' after wave 2; 'converge' after wave 3 or later

const SELECTION_ITEM = {
  type: 'object',
  properties: {
    group: { type: 'string', description: 'topic slug WITHOUT the cmake- prefix; reuse an existing group slug to have that consolidation REVISED rather than re-created' },
    group_label: { type: 'string' }, id_family: { type: 'string' }, slug: { type: 'string' }, label: { type: 'string' },
    kind: { type: 'string', enum: ['web', 'exemplar', 'measure'] },
    brief: { type: 'string' },
  },
  required: ['group', 'group_label', 'id_family', 'slug', 'label', 'kind', 'brief'],
}

const SCHEMA = {
  type: 'object',
  properties: {
    path: { type: 'string' },
    verdict: { type: 'string', enum: ['next-wave', 'ready-to-draft'] },
    verdict_reason: { type: 'string' },
    next_wave: { type: 'array', items: SELECTION_ITEM, description: 'the commissioned next wave: at most 14 dives, at most 4 measure; empty when ready-to-draft' },
    frame_corrections: { type: 'array', items: { type: 'string' } },
    rule_totals: { type: 'object', properties: { ids: { type: 'number' }, must: { type: 'number' }, families: { type: 'number' } }, required: ['ids', 'must', 'families'] },
    contradictions_across_consolidations: { type: 'array', items: { type: 'string' } },
    authoring_notes: { type: 'array', items: { type: 'string' }, description: 'binding instructions for the phase-7 drafters (converge mode; may be empty in commission mode)' },
    owner_decisions_outstanding: { type: 'array', items: { type: 'string' } },
  },
  required: ['path', 'verdict', 'verdict_reason', 'next_wave', 'frame_corrections', 'rule_totals', 'contradictions_across_consolidations', 'authoring_notes', 'owner_decisions_outstanding'],
}

const COMMON = `Model rationale: opus — ruling on surprises, commissioning a wave and deciding convergence are decisions with a blast radius over every artifact the program ships.

PROJECT CONTEXT (context for you, not content to reproduce):
- You are phase 6 (Iterate) of the research-lang program for CMake and C++ package management and their interoperability (companion to the shipped bazel-quality set), after wave ${WAVE}. Run from ${ROOT} (a git worktree; treat it as the repository root; never cd to /home/mherwig/dev/grimoire-lore).
- Read, in this order and in full: ${ROOT}/.claude/skills/research-lang/references/wave-plan.md (Phase 5 revision contract, Convergence, Budget) and ${ROOT}/.claude/skills/research-lang/references/rule-distillation.md; ${RESEARCH}/cmake-frame.md (every Corrections block; later wins); ${RESEARCH}/cmake-topic-map.md in full including every earlier "Wave N landed" append; then EVERY consolidation ${RESEARCH}/cmake-<group>.md now on disk (${H.consolidations.join(', ')}) and each group's verification ledger cmake-<group>/verification-wave<N>.md. Open individual dive files only where a surprise or a conflict needs it.
- Measurement is available on this host (CMake 3.31.12, 4.3.4, 4.4.2 via 'ocx package exec kitware/cmake:<3.31|4.3|4.4> -- cmake'; ninja via ocx; gcc for C; /opt/zig/zig c++ for C++; scratch under /home/mherwig/.cache/cmake-measure-scratch/, never /tmp). The exemplar corpus is at /home/mherwig/.cache/research-lang/exemplars/cmake. A commissioned 'measure' dive is the right answer to any contested behavioural claim.
- Owner decisions: the owner set the program to continue autonomously, so the map's "Questions for the owner" defaults stand unless the corpus found evidence that changes one — say so explicitly if it does.
- Budget is real: at most 14 dives per wave, at most 4 of them 'measure', and each dive must be justified by a load-bearing question.

WAVE ${WAVE} RECEIPT (structured; the files are authoritative where they differ):
${JSON.stringify(H.receipt, null, 1)}
`

const COMMISSION = `DO THREE THINGS.

1. APPEND to ${RESEARCH}/cmake-topic-map.md (never rewrite earlier sections) a section "## Wave ${WAVE} landed (${DATE})" with: (a) per group: consolidation path, ID count, MUST count, conflicts resolved, verifier corrections, follow-ups named; (b) "Surprises" — every surprise in the receipt with a verdict (promote to wave ${NEXT} / fold into a staged brief / defer with an M-ID / reject), one line of reason each; (c) "Map rows affected" — M-IDs now covered, split, merged or re-prioritised; (d) "Frame corrections"; (e) "Cross-consolidation contradictions so far" — pairs of rules across the consolidations that conflict or overlap, each with the resolution and which ID keeps the text.

2. COMMISSION wave ${NEXT}: take the map's "Staged for wave 3" briefs, REVISE each in light of what wave ${WAVE} settled (drop a brief whose question is now answered; sharpen one whose question moved; keep the group slug of an existing consolidation where the new dive deepens it so that consolidation is REVISED rather than re-created), and ADD commissions for every load-bearing follow-up and promoted surprise. At most 14 dives, at most 4 'measure'. Every brief is 10-25 lines written as a professional commission (sources to fetch, commands and versions to run, exemplar evidence to test against, what the deliverable must DECIDE) and is handed to a sonnet worker verbatim. Append the final list to the same section as "Commissioned for wave ${NEXT}" with one line per dive.

3. RETURN the structured receipt with verdict next-wave, next_wave carrying the full briefs verbatim, rule_totals across every consolidation on disk, and authoring_notes empty unless something already binds the drafters.

Rules: no claim without a source key, a path, a rule ID or a measurement; use read-only tools except for the one append to cmake-topic-map.md; do not launch anything; do not edit any consolidation.`

const CONVERGE = `DO THREE THINGS.

1. APPEND to ${RESEARCH}/cmake-topic-map.md (never rewrite earlier sections) a section "## Wave ${WAVE} landed (${DATE})" with: (a) per group: consolidation path, ID count, MUST count, conflicts resolved, verifier corrections, follow-ups; (b) "Surprises" with a verdict each; (c) "Frame corrections"; (d) "Cross-consolidation contradictions" — read ALL consolidations' rulesets against each other and list every pair that conflicts or overlaps (two families answering the same question differently for the same file kind is a conflict; the same fact stated with different version floors is a conflict), each with the resolution the drafters must apply and which ID keeps the text; (e) "Convergence" — apply the wave-plan's stop condition honestly: new MUST rules in freshly opened families are expected and do not by themselves fail it; what decides is whether any remaining open question is load-bearing AND answerable by a source read or a measurement on this host. Classify every open question across all consolidations as dated re-check / measurement this host cannot supply / owner decision / answerable-now. If any are answerable-now and load-bearing, the verdict is next-wave and the next wave is exactly those (at most 8 dives, full briefs). Otherwise ready-to-draft. (f) "Residue" — what the program deliberately leaves open.

2. If ready-to-draft, WRITE "## Authoring notes (binding on the drafters)" in the same append: the two rules and their exact glob lists (re-check each against rule-distillation's cannot-miss bar with the corpus counts); every depth file with the ID family it owns and the two or three consolidation sections it draws from; which rules are index-owned (CMK-CORE, CMK-PKG) versus depth-owned; the bounded-duplication list (the handful of MUST rows that appear in both rule indexes or in a skill, by ID); the pinned decisions and defaults (the floor and gate convention, the configure-gate spelling per CMake line, gersemi as formatter of record, CPS stance, the provider stance); the rules to DROP at authoring time because the model already does them, they lack a verification, or they rest only on argued evidence (name IDs); the version-dating convention (every version-specific row names the version and the date verified); the verification-command shape (explicit directory operand with -r; --include='*.ext' quoted; one -e per alternative; no \\| in a pattern and no unescaped | in a table cell; no <placeholder> inside a pattern; no $(...) operands; | xargs -r; state what empty output means); the fenced-block tagging and ruff-format constraint; the portability rule (no fleet paths, no OCX product names; find_ocx appears only as an anonymised worked example); the skills' scope (cmake-dependency-triage and cmake-modernize are procedures only and duplicate the MUST rows they enforce in a | # | Finding | Rule | table, never as rule-ID-first rows); the bazel-quality pointer patch (one line, proposed, not applied by the drafters); and the docs companion and bundle shape (untagged members).

3. RETURN the structured receipt. rule_totals counts across all consolidations. owner_decisions_outstanding lists what is still the owner's call, with the default the drafters assume.

Rules: no claim without a source key, a path, a rule ID or a measurement; use read-only tools except for the one append to cmake-topic-map.md; do not launch anything; do not edit any consolidation — record resolutions in the append and name which ID's text the drafters keep.`

phase('Harvest')
const r = await agent(COMMON + '\n' + (MODE === 'commission' ? COMMISSION : CONVERGE),
  { label: 'harvest:wave' + WAVE, phase: 'Harvest', model: 'opus', effort: 'high', schema: SCHEMA })

if (!r) { log('HARVEST RETURNED NULL — read journal.jsonl'); return { harvest: null } }
log('Verdict: ' + r.verdict + ' · next wave ' + r.next_wave.length + ' dives · IDs ' + r.rule_totals.ids + ' · MUST ' + r.rule_totals.must + ' · families ' + r.rule_totals.families + ' · contradictions ' + r.contradictions_across_consolidations.length + ' · notes ' + r.authoring_notes.length)
return { harvest: r }
